"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["3374"],{3856:function(i,n,l){l.r(n),l.d(n,{default:function(){return a}});var d=l(1147);let u=["innerHTML"],a={setup:()=>({html:""}),render:()=>((0,d.wg)(),(0,d.iD)("div",{class:"mi-doc-markdown-body",innerHTML:'<h1>项目定位</h1>\n<div class="mi-doc-card"><h3 id="wo-men-zai-jie-jue-shi-me-wen-ti" tabindex="-1">我们在解决什么问题</h3>\n<p>Miracle UI 的目标不是单纯提供“越多越好”的基础组件，而是帮助 Vue 3 的移动业务团队更快搭建一致、可维护、可发布的 H5 页面。</p>\n</div><div class="mi-doc-card"><h3 id="dui-shui-zui-you-jie-zhi" tabindex="-1">对谁最有价值</h3>\n<ul>\n<li>需要沉淀业务组件和页面模式的团队</li>\n<li>需要统一表单、筛选、选择器、上传、导航交互的项目</li>\n<li>希望通过主题变量和文档站形成长期规范的组件库维护者</li>\n</ul>\n</div><div class="mi-doc-card"><h3 id="dui-shui-bu-shi-zui-jia-xuan-ze" tabindex="-1">对谁不是最佳选择</h3>\n<ul>\n<li>主要做桌面端后台和复杂表格的项目</li>\n<li>需要跨端渲染或原生能力封装的项目</li>\n<li>更适合一次性接入完整企业级设计系统的团队</li>\n</ul>\n</div><div class="mi-doc-card"><h3 id="yu-chang-jian-zu-jian-ku-de-chai-yi" tabindex="-1">与常见组件库的差异</h3>\n<ul>\n<li>更强调移动业务 H5 场景，而不是桌面端通用能力</li>\n<li>更强调场景组合与推荐组合方式，而不只是单个组件文档</li>\n<li>更强调主题变量、暗黑模式、发布节奏等工程化约束</li>\n</ul>\n</div><div class="mi-doc-card"><h3 id="wo-men-de-you-xian-ji" tabindex="-1">我们的优先级</h3>\n<ol>\n<li>先把高频业务场景做顺手</li>\n<li>再补足关键基础能力短板</li>\n<li>最后再考虑更大范围的平台化扩展</li>\n</ol>\n</div>'},null,8,u))}}}]);